Bash(/tmp/verify-tags.mjs << 'EOF'
import pkg from 'contentful-management';
const { createClient } = pkg;
import 'dotenv/config';

const SPACE_ID = process.env.CONTENTFUL_SPACE_ID;
const MANAGEMENT_TOKEN = process.env.CONTENTFUL_MANAGEMENT_TOKEN;

const client = createClient\({
  accessToken: MANAGEMENT_TOKEN,
}\);

async function verifyTags\(\) {
  try {
    const space = await client.getSpace\(SPACE_ID\);
    const environment = await space.getEnvironment\('master'\);

    // Get the latest uploaded asset
    const asset = await environment.getAsset\('3DIiLxAFxdztvi6mZ4jNXW'\);

    console.log\('✅ Asset ID:', asset.sys.id\);
    console.log\('✅ Asset Title:', asset.fields.title['da-DK']\);
    console.log\('✅ Asset Version:', asset.sys.version\);
    console.log\('✅ Asset Metadata:'\);
    console.log\(JSON.stringify\(asset.metadata, null, 2\)\);

    // Check if tags are present
    if \(asset.metadata.tags && asset.metadata.tags.length > 0\) {
      console.log\('\\n🎉 SUCCESS! Tags are present:'\);
      asset.metadata.tags.forEach\(tag => {
        console.log\(`   - ${tag.sys.id}`\);
      }\);
    } else {
      console.log\('\\n❌ FAILED! No tags found on asset'\);
    }

  } catch \(error\) {
    console.error\('Error:', error.message\);
  }
}

verifyTags\(\);
EOF)
